def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # The final round has no future retaliation; defection dominates.
    if n >= 99:
        return 'D'

    last_me, last_op = history[-1]
    prev_me, prev_op = history[-2] if n >= 2 else ('', '')

    my_c = 0
    op_c = 0
    for a, b in history:
        if a == 'C':
            my_c += 1
        if b == 'C':
            op_c += 1

    op_d = n - op_c
    my_d = n - my_c

    w5 = min(5, n)
    w10 = min(10, n)
    w20 = min(20, n)

    rec5_opp_c = sum(1 for a, b in history[-w5:] if b == 'C')
    rec10_opp_c = sum(1 for a, b in history[-w10:] if b == 'C')
    rec20_opp_c = sum(1 for a, b in history[-w20:] if b == 'C')

    # Learn how the opponent responds when we defect against cooperation.
    tolerated = 0
    punished = 0
    for i in range(n - 1):
        a, b = history[i]
        if a == 'D' and b == 'C':
            if history[i + 1][1] == 'D':
                punished += 1
            else:
                tolerated += 1

    exploit_streak = 0
    for a, b in reversed(history):
        if a == 'D' and b == 'C':
            exploit_streak += 1
        else:
            break

    total_strong = op_c * 10 >= n * 8
    total_good = op_c * 10 >= n * 7
    total_ok = op_c * 10 >= n * 5
    total_bad = n >= 6 and op_c * 3 <= n

    recent_strong = rec10_opp_c * 10 >= w10 * 8
    recent_good = rec10_opp_c * 10 >= w10 * 6
    recent_ok = rec10_opp_c * 10 >= w10 * 5
    recent_bad = rec10_opp_c * 10 <= w10 * 3

    # If the opponent has never defected, preserve cooperation first.
    # Once they have tolerated an exploit, switch on opportunistic exploitation.
    if op_d == 0:
        if last_me == 'D':
            # Do not keep escalating on the first probe; let them respond.
            if tolerated >= 1:
                return 'D' if rng.random() < 0.92 else 'C'
            return 'C'

        if tolerated >= 1:
            return 'D' if rng.random() < 0.90 else 'C'

        # A few very late, low-risk probes against apparently pure cooperators.
        if n >= 96:
            return 'D' if rng.random() < 0.35 else 'C'
        if n >= 90:
            return 'D' if rng.random() < 0.08 else 'C'
        if n >= 80:
            return 'D' if rng.random() < 0.02 else 'C'
        if rng.random() < 0.005:
            return 'D'
        return 'C'

    # Very hostile recently and overall: stay defensive, avoid costly peace offerings.
    if total_bad and recent_bad:
        if last_op == 'D':
            if last_me == 'D':
                return 'C' if rng.random() < 0.04 else 'D'
            return 'C' if rng.random() < 0.02 else 'D'

        # Opponent cooperated.
        if last_me == 'D':
            if recent_ok and tolerated > punished:
                return 'C' if rng.random() < 0.45 else 'D'
            return 'C' if rng.random() < 0.15 else 'D'

        if recent_ok:
            return 'C' if rng.random() < 0.20 else 'D'
        return 'D' if rng.random() < 0.75 else 'C'

    # Adaptive reciprocity with context-sensitive forgiveness.
    if last_op == 'D':
        # If this looks like a predictable punishment of our earlier D, repair.
        if prev_me == 'D' and prev_op == 'C':
            if last_me == 'C':
                return 'C' if rng.random() < 0.90 else 'D'
            return 'C' if rng.random() < 0.60 else 'D'

        # Mutual defection: break out when there is evidence they are not stubborn.
        if last_me == 'D':
            if total_good and recent_ok:
                return 'C' if rng.random() < 0.70 else 'D'
            if total_ok and recent_good:
                return 'C' if rng.random() < 0.55 else 'D'
            if op_c >= op_d:
                return 'C' if rng.random() < 0.40 else 'D'
            return 'D' if rng.random() < 0.80 else 'C'

        # Unprovoked or unclear defection against our cooperation: retaliate.
        # Very cooperative opponents may occasionally get a small forgiveness chance.
        if total_strong and op_d <= max(1, n // 10) and rec5_opp_c >= 4:
            return 'C' if rng.random() < 0.12 else 'D'
        if total_good and punished >= 2 and tolerated > punished:
            return 'C' if rng.random() < 0.25 else 'D'
        return 'D'

    # Opponent cooperated last.
    if last_me == 'D':
        # We just exploited them. If they have already tolerated a prior exploit,
        # keep probing; otherwise repair cooperation and let them respond.
        if punished == 0 and (tolerated >= 1 or exploit_streak >= 2):
            if recent_strong or total_strong or n >= 95:
                return 'D' if rng.random() < 0.75 else 'C'
        if n >= 95 and recent_ok and tolerated > punished:
            return 'D' if rng.random() < 0.45 else 'C'
        return 'C'

    # Mutual cooperation: stay nice, but exploit endgame and tolerant opponents.
    if n >= 95:
        if total_strong:
            return 'D' if rng.random() < 0.55 else 'C'
        if total_good:
            return 'D' if rng.random() < 0.30 else 'C'
        if recent_strong:
            return 'D' if rng.random() < 0.20 else 'C'
        return 'C'

    if n >= 90:
        if total_good and (punished == 0 or tolerated >= punished):
            return 'D' if rng.random() < 0.20 else 'C'
        if recent_strong:
            return 'D' if rng.random() < 0.10 else 'C'
        if total_ok or recent_good:
            return 'D' if rng.random() < 0.12 else 'C'
        return 'C' if rng.random() < 0.30 else 'D'

    if total_good:
        if punished == 0 and tolerated >= 1 and n >= 60:
            return 'D' if rng.random() < 0.12 else 'C'
        return 'D' if rng.random() < 0.03 else 'C'

    if recent_good:
        return 'D' if rng.random() < 0.06 else 'C'

    if op_c >= op_d:
        return 'C' if rng.random() < 0.90 else 'D'

    if recent_ok and tolerated > punished:
        return 'C' if rng.random() < 0.40 else 'D'

    return 'D' if rng.random() < 0.75 else 'C'
